classdef IBackwardPass < handle
    % IBACKWARDPASS Interface for stepwise backward pruning algorithms.
    % 
    % The backward pass prunes an overly large additive model produced by the 
    % forward pass by removing the least significant basis functions.
    
    methods (Abstract)
        % PRUNE
        % Prunes the basisList to find the optimal submodel.
        %
        % INPUTS:
        %   X         - (N x P) feature matrix
        %   Y         - (N x 1) target vector
        %   basisList - cell array of IBasisFunction generated by ForwardPass
        %   options   - struct of boundaries (PenaltyCost, etc)
        %
        % OUTPUTS:
        %   bestBasisList - cell array of the optimal subset
        %   bestCoefs     - corresponding OLS coefficients
        %   history       - struct array containing the sequence of nested models
        [bestBasisList, bestCoefs, history] = prune(obj, X, Y, basisList, options);
    end
end
